<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch} from 'vue'
import {session,logout} from '../auth'
import {useRoute,useRouter} from 'vue-router'
const router=useRouter(),route=useRoute(),legs=ref<any[]>([]),wallets=ref<any[]>([]),wallet=ref(''),direction=ref('BUY'),quantity=ref(''),items=ref<any[]>([]),message=ref(''),busy=ref(false),menuOpen=ref(false),closeOriginal=ref<any>(null),closeInfo=ref<any>(null)
const stateName=(state:string)=>({requesting:'询价中',quoted:'已报价',accepting:'确认中',executing:'执行中，未确认成交',confirmed:'已确认',expired:'已过期',rejected:'已拒绝',failed:'未成交',unknown:'结果未知'} as Record<string,string>)[state]||'未知'
const nextCursor=ref<string|null>(null)
const activeQuote=ref<any>(null)
const clock=ref(Date.now()), blockedAccepts=ref<string[]>([])
const blockKey='polysports_combo_accept_unresolved'
const remaining=(row:any)=>Math.max(0,Math.ceil((Date.parse(row.quote?.expires_at)-clock.value)/1000))
const isBlocked=(row:any)=>blockedAccepts.value.includes(row.id+':'+row.quote?.id)
function setBlocked(id:string,blocked:boolean){blockedAccepts.value=blocked?[...new Set([...blockedAccepts.value,id])]:blockedAccepts.value.filter(x=>x!==id);try{localStorage.setItem(blockKey,JSON.stringify(blockedAccepts.value))}catch{/* 内存中仍禁止重复提交 */}}
const key='polysports_combo_legs',pendingKey='polysports_combo_pending';const pending=ref<any>(null),ack=ref(false)
async function api(path:string,options:RequestInit={}){const r=await fetch('/api/v1'+path,{credentials:'same-origin',cache:'no-store',...options});const body=await r.json();if(!r.ok){const e=new Error(body.error?.message||'请求失败');(e as any).code=body.error?.code;throw e}return body.data}
async function load(more=false){try{const [w,r]=await Promise.all([api('/wallets'),api('/combo-rfqs'+(more&&nextCursor.value?'?cursor='+encodeURIComponent(nextCursor.value):''))]);wallets.value=w.items;items.value=more?[...items.value,...r.items]:r.items;nextCursor.value=r.next_cursor||null;if(!wallet.value&&wallets.value.length)wallet.value=wallets.value[0].id}catch{message.value='读取钱包或组合记录失败。'}}
function remove(i:number){legs.value.splice(i,1);localStorage.setItem(key,JSON.stringify(legs.value))}
async function quote(){if(busy.value)return;busy.value=true;message.value='';const old=localStorage.getItem(pendingKey);if(old){message.value='上次询价结果未确认，请查询记录，勿重复询价。';busy.value=false;return}const id=crypto.randomUUID();try{localStorage.setItem(pendingKey,JSON.stringify({key:id,wallet_id:wallet.value}));pending.value={key:id,wallet_id:wallet.value}}catch{message.value='无法保存请求标识，未发送询价。';busy.value=false;return}try{const data=await api('/combo-rfqs',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf,'Idempotency-Key':id},body:JSON.stringify({wallet_id:wallet.value,direction:direction.value,quantity:quantity.value,legs:legs.value.map(x=>({market_link_id:x.market_link_id,outcome_id:x.outcome_id})),...(closeOriginal.value?{parent_combo_id:closeOriginal.value.id}:{})})});if(!['requesting','unknown'].includes(data.state)){localStorage.removeItem(pendingKey);pending.value=null}if(data.state==='quoted' && data.quote){clock.value=Date.now();activeQuote.value=data;items.value=[data,...items.value.filter(x=>x.id!==data.id)]}else{activeQuote.value=null;await load()}message.value=['requesting','unknown'].includes(data.state)?'询价结果未确认，请查询原记录，不要重复请求。':data.state==='quoted'?'已获得报价，请在有效期内核对并确认。':data.error_code==='no_quote'?'本次没有收到报价，未成交。':data.state==='rejected'?'上游拒绝本次询价，请检查账户权限及组合选项。':'已记录组合询价，请查看状态。'}catch(e){const code=(e as any)?.code;const safe=['COMBO_DISABLED','COMBO_CLOSE_INVALID','MAPPING_INVALID','INVALID_AMOUNT','COMBO_LEGS_INVALID','COMBO_LEGS_DUPLICATE','COMBO_MARKET_UNAVAILABLE','COMBO_CATALOG_UNAVAILABLE','COMBO_CATALOG_INCOMPLETE','COMBO_MARKET_MISMATCH','COMBO_OUTCOME_UNSUPPORTED','COMBO_OUTCOME_MISMATCH','COMBO_POSITION_INVALID','CREDENTIALS_MISSING','BUILDER_CREDENTIALS_MISSING','COMBO_WALLET_UNSUPPORTED','WALLET_NOT_FOUND','WALLET_MISMATCH','SIGNER_MISMATCH','GEOBLOCK_BLOCKED','GEOBLOCK_UNKNOWN','WALLET_UNDEPLOYED','WALLET_DEPLOYMENT_UNKNOWN'];if(safe.includes(code)){localStorage.removeItem(pendingKey);pending.value=null;message.value=e instanceof Error?e.message:'询价未发送，请检查配置。'}else message.value='询价结果未确认，请查看交易记录并独立核对，勿重复请求。'}finally{busy.value=false}}
async function accept(row:any){
  if(!row.quote||busy.value||isBlocked(row)||!Number.isFinite(remaining(row))||remaining(row)<=0)return
  busy.value=true;message.value='正在确认报价，请稍候，执行中不代表成交。'
  const acceptId=row.id+':'+row.quote.id
  setBlocked(acceptId,true)
  try{
    const result=await api('/combo-rfqs/'+row.id+'/accept',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf},body:JSON.stringify({quote_id:row.quote.id})})
    activeQuote.value=null;await load()
    message.value=result.state==='unknown'?'确认结果未知，请查看记录，不要重复提交。':'已处理确认请求；当前状态：'+stateName(result.state)+'。'
  }catch(e){
    const code=(e as any)?.code
    const beforeSend=['QUOTE_UNAVAILABLE','COMBO_QUOTE_EXPIRED','COMBO_QUOTE_MISMATCH','WALLET_MISMATCH','SIGNER_MISMATCH','CREDENTIALS_MISSING','BALANCE_INSUFFICIENT','ALLOWANCE_INSUFFICIENT','COMBO_FUNDING_UNKNOWN','MAPPING_INVALID','COMBO_MARKET_MISMATCH','COMBO_CATALOG_UNAVAILABLE','COMBO_CATALOG_INCOMPLETE','COMBO_MARKET_UNAVAILABLE','COMBO_OUTCOME_UNSUPPORTED','COMBO_OUTCOME_MISMATCH','COMBO_POSITION_INVALID','GEOBLOCK_BLOCKED','GEOBLOCK_UNKNOWN','WALLET_UNDEPLOYED','WALLET_DEPLOYMENT_UNKNOWN','COMBO_DISABLED']
    const known=beforeSend.includes(code)
    if(known)setBlocked(acceptId,false)
    activeQuote.value=null;await load()
    message.value=known?(e instanceof Error?e.message:'接受前检查未通过。')+'（本次未发送接受请求）':'确认结果未核实，请查看记录，不要重复提交。'
  }finally{busy.value=false}
}
async function lookup(){if(!pending.value)return;try{const data=await api('/combo-rfqs/by-key/'+pending.value.key+'?wallet_id='+encodeURIComponent(pending.value.wallet_id));message.value='已找到记录，状态：'+data.state;if(!['requesting','unknown'].includes(data.state)){localStorage.removeItem(pendingKey);pending.value=null}await load()}catch{message.value='未能找到记录，请独立核对，不要重新询价。'}}
function clearPending(){if(!ack.value)return;localStorage.removeItem(pendingKey);pending.value=null;ack.value=false}
let ticker:ReturnType<typeof setInterval>|undefined,closeRevision=0
async function initialize(){
  const revision=++closeRevision,closeId=route.query.close
  closeOriginal.value=null;closeInfo.value=null;activeQuote.value=null
  await load()
  if(revision!==closeRevision)return
  if(typeof closeId!=='string'){
    direction.value='BUY';quantity.value=''
    try{const saved=JSON.parse(localStorage.getItem(key)||'[]');legs.value=Array.isArray(saved)?saved:[]}catch{legs.value=[]}
    return
  }
  try{
    const [original,position]=await Promise.all([api('/combo-rfqs/'+encodeURIComponent(closeId)),api('/combo-rfqs/'+encodeURIComponent(closeId)+'/close-context')])
    if(revision!==closeRevision)return
    if(original.state!=='confirmed'||original.direction!=='BUY'||!original.quote?.net_receive||!Array.isArray(original.legs)||original.legs.length<2||!wallets.value.some((item:any)=>item.id===original.wallet_id))throw new Error('原组合成交或钱包无法核实')
    if(position.wallet_id!==original.wallet_id || (original.combo_position_id && position.position_id!==original.combo_position_id))throw new Error('原组合钱包或持仓身份不一致')
    closeOriginal.value=original;closeInfo.value=position;wallet.value=original.wallet_id;direction.value='SELL'
    quantity.value=String(position.candidate_shares).replace(/(\.\d*?)0+$/,'$1').replace(/\.$/,'')
    legs.value=original.legs.map((leg:any)=>({market_link_id:leg.market_link_id,outcome_id:leg.outcome_id,label:leg.home+' 对 '+leg.away+' · '+leg.market_question+' · '+leg.outcome_label}))
    message.value='组合平仓：请核对原组合及卖出份额，再请求真实卖出报价。'
  }catch(e){if(revision===closeRevision){legs.value=[];message.value=e instanceof Error?e.message:'无法读取原组合，不能平仓。'}}
}
onMounted(()=>{try{pending.value=JSON.parse(localStorage.getItem(pendingKey)||'null');const saved=JSON.parse(localStorage.getItem(blockKey)||'[]');blockedAccepts.value=Array.isArray(saved)?saved.filter(x=>typeof x==='string'):[]}catch{legs.value=[]}ticker=setInterval(()=>{clock.value=Date.now()},250);void initialize()})
watch(()=>route.query.close,()=>{void initialize()})
onUnmounted(()=>{closeRevision++;if(ticker)clearInterval(ticker)})
</script>
<template><div class="app-layout"><header class="mobile-header"><div class="brand">PolySports</div><button class="menu-button" :aria-expanded="menuOpen" aria-controls="primary-nav" @click="menuOpen=!menuOpen">菜单</button></header><aside id="primary-nav" class="sidebar" :class="{open:menuOpen}"><div class="brand sidebar-brand">PolySports</div><nav><RouterLink to="/">总览</RouterLink><RouterLink to="/sports/football">足球赛事</RouterLink><RouterLink to="/sports/nba">NBA 赛事</RouterLink><RouterLink to="/combos">组合交易</RouterLink><RouterLink to="/orders">交易记录</RouterLink><RouterLink to="/history">历史与导出</RouterLink><RouterLink to="/wallets">钱包状态</RouterLink><RouterLink to="/system">系统管理</RouterLink></nav></aside><main class="workspace combo-page"><div class="workspace-top"><span>工作台 / 组合交易</span><button class="text-button" @click="logout().then(()=>router.replace('/login'))">退出</button></div><h1>{{closeOriginal ? '组合平仓' : '组合询价'}}</h1><p>从赛事市场中选择至少两条腿。确认报价后可能使用真实资金；执行中不代表成交。</p><p role="status">{{message}}</p><section v-if="pending" class="welcome-card"><p>上次询价结果未确认，请先用原请求标识查询。</p><button class="text-button" @click="lookup">查询原请求</button><label><input type="checkbox" v-model="ack">我已独立核实外部状态，理解重复询价风险</label><button class="text-button" :disabled="!ack" @click="clearPending">清除本机待查记录</button></section><section class="welcome-card"><p v-if="!legs.length">请先在赛事中心选择已确认的市场选项。</p><p v-for="(leg,index) in legs" :key="leg.outcome_id">{{leg.label}} <button v-if="!closeOriginal" class="text-button" @click="remove(index)">移除</button></p><label>钱包 <select v-model="wallet" :disabled="!!closeOriginal"><option v-for="w in wallets" :key="w.id" :value="w.id">{{w.label}} · {{w.wallet_address}}</option></select></label><label>方向 <select v-model="direction" :disabled="!!closeOriginal"><option value="BUY">买入</option><option value="SELL">卖出</option></select></label><label>{{direction==='BUY'?'最高预算（含费用）':'出售份额'}} <input v-model="quantity" inputmode="decimal"></label><div v-if="closeInfo"><p>原组合候选可卖份额：{{closeInfo.candidate_shares}} · 钱包当前份额：{{closeInfo.wallet_shares ?? '未知（报价后核验）'}} · 已平仓：{{closeInfo.previously_closed_shares}} · 授权：{{closeInfo.approved === true ? '已授权' : closeInfo.approved === false ? '未授权' : '待核验'}}</p><p>{{closeInfo.notice}}</p><p>卖出报价要求全部指定份额成交；接受前会再次核验钱包余额和授权。</p></div><button class="text-button" :disabled="busy||legs.length<2||!wallet||!quantity || (!!route.query.close && (!closeOriginal || closeInfo?.approved===false || Number(closeInfo?.candidate_shares)<=0))" @click="quote">{{closeOriginal ? '请求真实卖出报价' : '请求真实报价'}}</button><div v-if="activeQuote && activeQuote.quote" class="market-card" role="region" aria-label="最新组合报价"><h2>最新组合报价</h2><p v-for="leg in activeQuote.legs" :key="leg.outcome_id">{{leg.home}} 对 {{leg.away}} · {{leg.market_question}} · {{leg.outcome_label}}</p><p v-if="closeOriginal">组合持仓标识：{{activeQuote.combo_position_id || '未知'}}；请核对全部卖出份额及预期收入。</p><p>报价：{{activeQuote.quote.price}} · 实际需求：{{activeQuote.quote.total_required}} · {{activeQuote.direction==='BUY'?'预计组合份额':'扣费后收入'}}：{{activeQuote.quote.net_receive ?? '未知'}}</p><p v-if="!Number.isFinite(remaining(activeQuote)) || remaining(activeQuote)<=0">报价已过期，不能接受，请重新询价。</p><p v-else>报价剩余：{{remaining(activeQuote)}} 秒</p><p v-if="isBlocked(activeQuote)">本次确认结果待核实，请勿重复提交。</p><button class="text-button" :disabled="busy || isBlocked(activeQuote) || !Number.isFinite(remaining(activeQuote)) || remaining(activeQuote)<=0" @click="accept(activeQuote)">{{busy ? '处理中…' : '确认接受真实资金报价'}}</button></div></section><section class="welcome-card"><h2>组合记录</h2><button class="text-button" @click="load()">刷新状态</button><p v-if="!items.length">暂无组合记录。</p><article v-for="row in items" :key="row.id" class="market-card"><p>状态：{{stateName(row.state)}} · 方向：{{row.direction}} · 数量：{{row.quantity}} · 钱包：{{row.wallet_address}}</p><p v-for="leg in row.legs" :key="leg.outcome_id">{{leg.home}} 对 {{leg.away}} · {{leg.market_question}} · {{leg.outcome_label}} · {{new Date(leg.starts_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}} UTC+8</p><p>RFQ：{{row.external_rfq_id || '未知'}} · {{row.error_code || ''}}</p><p v-if="row.quote">报价：{{row.quote.price}} · 实际需求：{{row.quote.total_required}} · {{row.direction==='BUY'?'预计组合份额':'扣费后收入'}}：{{row.quote.net_receive ?? '未知'}} · 截止：{{row.quote.expires_at}}</p><template v-if="row.state==='quoted' && row.quote"><p v-if="!Number.isFinite(remaining(row)) || remaining(row)<=0">报价已过期，不能接受，请重新询价。</p><p v-else>报价剩余：{{remaining(row)}} 秒</p><p v-if="isBlocked(row)">本次确认结果待核实，请勿重复提交。</p><button class="text-button" :disabled="busy || isBlocked(row) || !Number.isFinite(remaining(row)) || remaining(row)<=0" @click="accept(row)">{{busy ? '处理中…' : '确认接受真实资金报价'}}</button></template><p v-if="row.state==='unknown'">结果未知；请勿重复操作。</p></article><button v-if="nextCursor" class="text-button" @click="load(true)">加载更多</button></section></main></div></template>
